const norm = $('Normalize Payload').first().json;
const item = $input.first();
const DISCLAIMER = 'AI-generated draft for clinician review only. Not a diagnosis.';
const SUPPORTED = ['application/pdf', 'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'image/heif'];
const BY_EXTENSION = { pdf: 'application/pdf', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp', heic: 'image/heic', heif: 'image/heif' };

const describe = (err) => String(typeof err === 'string' ? err : (err?.message || err?.description || JSON.stringify(err))).slice(0, 300);
const fail = (limitations) => [{
  json: {
    ...norm,
    _fetchFailed: true,
    status: 'FAILED',
    ai_summary: {
      clinician_bullets: ['The report could not be analysed automatically. Open the original file from the doctor dashboard.'],
      abnormal_flags: [],
      confidence: 'low',
      limitations,
      disclaimer: DISCLAIMER,
    },
  },
}];

const binaryKey = item.binary ? Object.keys(item.binary)[0] : null;
if (!binaryKey) {
  const detail = item.json?.error ? describe(item.json.error) : 'no file returned';
  return fail(`Report download failed (${detail}). The signed link may have expired (24h), the file may be missing, or the app was still waking up.`);
}

const ext = String(norm.filename || '').split('.').pop().toLowerCase();
let mimeType = String(item.binary[binaryKey].mimeType || '').split(';')[0].trim().toLowerCase();
if (!mimeType || mimeType === 'application/octet-stream') {
  mimeType = norm.mime_type || BY_EXTENSION[ext] || '';
}
if (mimeType === 'text/html') {
  return fail('The download returned a web page instead of the report, usually because the signed link expired or was invalid.');
}
if (!SUPPORTED.includes(mimeType)) {
  return fail(`Unsupported file type "${mimeType || 'unknown'}". Upload a PDF, PNG, JPEG, WEBP or HEIC file.`);
}

const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const prompt = `You are a lab report drafting assistant for Primary Health Centre doctors in India.
You extract structured data from lab PDFs or images and draft notes for a duty doctor.
You do NOT diagnose. You do NOT state that the patient has a disease.
Use cautious language: "suggest review", "clinician to confirm".

Filename: ${norm.filename}
Appointment ID (if any): ${norm.appointment_id || 'N/A'}

Fill the JSON fields:
- clinician_bullets: at most 8 short bullets for the duty doctor
- abnormal_flags: one entry per out-of-range result (test, value with unit, note that the clinician confirms)
- confidence: high | medium | low
- limitations: scan quality, missing pages, unreadable text
- disclaimer: exactly "${DISCLAIMER}"

If the document is unreadable, return empty arrays, confidence "low", and explain in limitations.
Do not invent test names or values that are not visible in the document.`;

const geminiBody = {
  contents: [{
    role: 'user',
    parts: [
      { inline_data: { mime_type: mimeType, data: buffer.toString('base64') } },
      { text: prompt },
    ],
  }],
  generationConfig: {
    temperature: 0.2,
    maxOutputTokens: 8192,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        clinician_bullets: { type: 'ARRAY', items: { type: 'STRING' } },
        abnormal_flags: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: { test: { type: 'STRING' }, value: { type: 'STRING' }, note: { type: 'STRING' } },
            required: ['test', 'value', 'note'],
          },
        },
        confidence: { type: 'STRING', enum: ['high', 'medium', 'low'] },
        limitations: { type: 'STRING' },
        disclaimer: { type: 'STRING' },
      },
      required: ['clinician_bullets', 'abnormal_flags', 'confidence', 'limitations', 'disclaimer'],
    },
  },
};

return [{ json: { ...norm, mime_type: mimeType, _fetchFailed: false, status: 'PROCESSING', geminiBody } }];

const { geminiBody, ...norm } = $('Prepare Gemini Request').first().json;
const raw = $input.first().json;
const DISCLAIMER = 'AI-generated draft for clinician review only. Not a diagnosis.';

const describe = (err) => String(typeof err === 'string' ? err : (err?.message || err?.description || JSON.stringify(err))).slice(0, 300);
const fallback = (limitations) => ({
  clinician_bullets: ['AI analysis was not available. Review the original report manually.'],
  abnormal_flags: [],
  confidence: 'low',
  limitations,
  disclaimer: DISCLAIMER,
});

let status = 'DONE';
let ai_summary;
const candidate = raw.candidates?.[0];

if (raw.error || !candidate) {
  status = 'FAILED';
  const reason = raw.error ? describe(raw.error) : `no answer (${raw.promptFeedback?.blockReason || 'empty response'})`;
  ai_summary = fallback(`Gemini request failed: ${reason}`);
} else {
  const text = (candidate.content?.parts || [])
    .filter((part) => !part.thought && typeof part.text === 'string')
    .map((part) => part.text)
    .join('')
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');
  try {
    const parsed = JSON.parse(text);
    ai_summary = {
      clinician_bullets: (Array.isArray(parsed.clinician_bullets) ? parsed.clinician_bullets : []).map(String).slice(0, 8),
      abnormal_flags: (Array.isArray(parsed.abnormal_flags) ? parsed.abnormal_flags : []).map((flag) => ({
        test: String(flag?.test ?? ''),
        value: String(flag?.value ?? ''),
        note: String(flag?.note ?? 'Clinician to confirm.'),
      })),
      confidence: ['high', 'medium', 'low'].includes(parsed.confidence) ? parsed.confidence : 'low',
      limitations: String(parsed.limitations ?? ''),
      disclaimer: DISCLAIMER,
    };
  } catch (e) {
    status = 'FAILED';
    ai_summary = fallback(`Gemini reply was not valid JSON (finish reason: ${candidate.finishReason || 'unknown'}; ${e.message}).`);
  }
}

if (raw.modelVersion) ai_summary.model = raw.modelVersion;

return [{ json: { ...norm, status, ai_summary } }];
